    print("       galaxy    R_disk  Sigma_eff   gas | observed: eta     B   sig. (max; +Vflat)  extrema | PG: eta     B   extrema   h/ell  R_half/ell unsup.  v(R_last)/V_flat")
    rows = {}
    for nm in ("DDO154", "IC2574", "NGC2403", "NGC3198", "NGC6503", "NGC2841", "UGC02885", "NGC7814"):
        g = _v36_sparc(nm); o = pilot['pilot'][nm]; h = g['Rdisk']; R = g['R']; eV = np.maximum(g['eV'], 1e-3)
        seff = g['L36']*1e9/(2*PI*(h*1e3)**2)
        eta_o = float(np.interp(2*h, R, g['Vobs']))/g['Vflat'] if 2*h >= R[0] else float('nan')
        Bo, no = _v36_shape(g['Vobs'], g['Vflat'], 2*eV); im = int(np.argmax(g['Vobs'])); sig0 = (g['Vobs'][im] - g['Vflat'])/eV[im]
        eVf = _V36_SPARC_T1[nm][6]; sig = (g['Vobs'][im] - g['Vflat'])/np.sqrt(eV[im]**2 + eVf**2)
        Rf = np.unique(np.concatenate([np.geomspace(min(R[0], 0.5*h), R[-1], 50), [2*h]]))
        oo = _v36_sparc_pg(nm, Rx=Rf); sup = oo['v2x'] > 0; vf = np.sqrt(np.maximum(oo['v2x'], 0)); vl = vf[-1]
        eta_p = float(np.interp(2*h, Rf, vf))/vl if vl > 0 else float('nan')
        Bp, npg = _v36_shape(vf[sup], vl, 5e-3*vf[sup]) if sup.sum() > 2 and vl > 0 else (float('nan'), -1)
        Sst, Mst, Sg, Mg, bul, grms = _v36_sparc_sources(g); Rg = np.geomspace(1e-3*R[-1], 400*R[-1], 2000)
        cum = 2*PI*np.concatenate([[0.0], np.cumsum(0.5*(Rg[1:]-Rg[:-1])*(Rg[1:]*(Sst(Rg[1:]) + Sg(Rg[1:])) + Rg[:-1]*(Sst(Rg[:-1]) + Sg(Rg[:-1]))))])
        if bul: cum = cum + np.nan_to_num(bul[0](np.minimum(Rg, bul[2])), nan=bul[1])
        Rhalf = float(np.interp(0.5*cum[-1], cum, Rg))
        rows[nm] = dict(h=h, seff=seff, gas=o['Mgas']/o['Mb'], eta_o=eta_o, Bo=Bo, sig0=float(sig0), sig=float(sig), no=no, eta_p=eta_p, Bp=Bp, npg=npg, hl=h/o['ell'], rh=Rhalf/o['ell'],
                        nun=int(np.sum(~sup)), ratio=vl/g['Vflat'], first_max=(im == 0))
        r = rows[nm]
        print(f"       {nm:9s} {h:6.2f} {seff:9.1f} {r['gas']:6.2f} | {eta_o:9.2f} {Bo:+6.3f} {sig0:5.1f} {sig:6.1f}      {no:6d}    | {eta_p:7.2f} {Bp:+6.3f} {npg:6d} {r['hl']:9.3f} {r['rh']:8.2f} {r['nun']:5d} {r['ratio']:11.2f}")
