    kinds = ("rising", "bump", "declining", "unsupported"); word = {"rising": "no overshoot (rising or flat)", "bump": "bump", "declining": "declining", "unsupported": "no circular support"}
    print("   (d) The classes.  Observed: " + "; ".join(f"{word[k]}: {', '.join(n for n in rows if cls_o[n] == k) or 'none'}" for k in kinds[:3]) + ".")
    print("     PG from the measured sources on the arena leaf: " + "; ".join(f"{word[k]}: {', '.join(n for n in rows if cls_p[n] == k) or 'none'}" for k in kinds) + ".")
    agree = [n for n in rows if cls_p[n] == cls_o[n]]; dis6 = [n for n in rows if rows[n]['nun'] == 0 and cls_p[n] != cls_o[n]]
    bigger = [n for n in agree if cls_o[n] in ("bump", "declining") and rows[n]['Bp'] > 1.3*rows[n]['Bo']]
