    AC = lam2(np.diag([1, -1, -1, -1.0])); e_sw = max(np.linalg.norm(Pp.T @ AC @ Pp), np.linalg.norm(Pm.T @ AC @ Pm)); n_sw = np.linalg.norm(Pm.T @ AC @ Pp)
