    w1, w2 = np.exp(0.5j*ph)*z1, np.exp(0.5j*ph)*z2; e_lam = max(np.abs(w1 - np.exp(1j*ph)/np.sqrt(2)).max(), np.abs(w2 - 1/np.sqrt(2)).max(), np.abs(h(w1, w2) - h(z1, z2)).max())
