    fixes = [tuple(k for k in range(3) if _v37_lineperm(A_, 1, F)[k] == k) for A_ in A]
    e_conj = max(np.abs(C @ A[j] @ np.conj(Ci) - A[(j - 1) % 3]).max() for j in range(3))
    prods = {(0, 2): C, (0, 1): Ci, (1, 2): Ci}
