    eph = sorted(float(x) for x in np.angle(np.linalg.eigvals(A[0] @ np.conj(A[2]))))
    Rr = [np.block([[np.real(A_), np.imag(A_)], [np.imag(A_), -np.real(A_)]]) for A_ in A]      # kappa_j on the realification R^6 = C^3
    e_rr = max(np.abs(R_ @ R_ - np.eye(6)).max() for R_ in Rr)
    e_rr_ev = max(np.abs(np.sort(np.linalg.eigvalsh((R_ + R_.T)/2)) - np.array([-1, -1, -1, 1, 1, 1])).max() for R_ in Rr)
    e_rr_sym = max(np.abs(R_ - R_.T).max() for R_ in Rr)
