    e_fix1 = np.abs(A[1] @ np.conj(v1) - v1).max(); ph_ = 0.4; e_reph = np.abs(A[1] @ np.conj(np.exp(1j*ph_)*v1) - np.exp(-2j*ph_)*(np.exp(1j*ph_)*v1)).max()
    e_cev = np.abs(C @ I3 - I3 @ np.diag([1, w, w*w])).max()                                    # C e_j = w^j e_j
    # (d) the complexified rest space: b(z, w) = z^T w
    bF = F.T @ F; e_null = max(abs(bF[0, 0] - 1), abs(bF[1, 1]), abs(bF[2, 2]), abs(bF[1, 2] - 1), abs(bF[0, 1]), abs(bF[0, 2]))
    e_Tb = np.abs(T.T @ T - I3).max(); X = C.T @ C; d_conf = np.linalg.norm(X - np.trace(X)/3*I3)
    d_k = [np.linalg.norm(A_.T @ A_ - np.trace(A_.T @ A_)/3*I3) for A_ in A]
