        t0 = math.atan2(-_v37_d4(nn, a), _v37_d4(nn, v)); q1 = a*math.cos(t0) + v*math.sin(t0); q2 = a*math.cos(t0 + PI) + v*math.sin(t0 + PI)
        e_gc = max(e_gc, float(np.abs(q1 + q2).max()), abs(_v37_d4(nn, q1)), abs(_v37_d4(nn, q2)))
