        e_eig = max(e_eig, abs(tr/2 + disc - (r - M + d)), abs(tr/2 - disc - (r - M - d)))
        psi = math.atanh(Q/dK); ch, sh = math.cosh(psi/2), math.sinh(psi/2)
        S = [[ch, -sh], [-sh, ch]]; Si = [[ch, sh], [sh, ch]]                       # exp(-psi s1/2) and its inverse
