    Si = ((S[1][1], -S[0][1]), (-S[1][0], S[0][0]))
    K1 = (Si[0][0]*K[0][0] + Si[0][1]*K[0][1], Si[1][0]*K[0][0] + Si[1][1]*K[0][1])          # S^-1 K_0
    rank = 2 if K[0][0]*K[1][1] - K[0][1]*K[1][0] != 0 else 1
