    q = (lambda x, c: x, lambda x, c: (x + c) % n)
    npairs = len({(q[0](*p), q[1](*p)) for p in pts}); fib = min(len({q[1](x0, c) for c in range(n)}) for x0 in range(n))
    def classes(keys):
        par = {p: p for p in pts}
        def f(a):
            while par[a] != a:
                par[a] = par[par[a]]; a = par[a]
            return a
        for key in keys:
            first = {}
            for p in pts:
                k = key(*p)
                if k in first:
                    par[f(p)] = f(first[k])
                else:
                    first[k] = p
        return len({f(p) for p in pts})
