def _v377_q(a, b, c, d):
    """The unit quaternion a + b i + c j + d k as an SU(2) matrix: i -> i sigma_3, j -> i sigma_2, k -> i sigma_1."""
    return [[complex(a, b), complex(c, d)], [complex(-c, d), complex(a, -b)]]

def _v377_mm(A, B):
    return [[sum(A[i][k]*B[k][j] for k in range(2)) for j in range(2)] for i in range(2)]

def _v377_dag(A):
    return [[A[j][i].conjugate() for j in range(2)] for i in range(2)]

def _v377_bloch(psi):
    a, b = psi
    return (2*(a.conjugate()*b).real, 2*(a.conjugate()*b).imag, abs(a)**2 - abs(b)**2)

