def _v377_jacobi(A):
    """The eigenvalues of a real symmetric matrix, by cyclic Jacobi rotations (pure Python)."""
    n = len(A); A = [row[:] for row in A]
    for _ in range(100):
        off = sum(A[i][j]**2 for i in range(n) for j in range(n) if i != j)
        if off < 1e-30:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                if abs(A[p][q]) < 1e-300:
                    continue
                th = (A[q][q] - A[p][p])/(2*A[p][q])
                t = (1.0 if th >= 0 else -1.0)/(abs(th) + math.sqrt(th*th + 1)); c = 1/math.sqrt(t*t + 1); s = t*c
                for k in range(n):
                    akp, akq = A[k][p], A[k][q]
                    A[k][p], A[k][q] = c*akp - s*akq, s*akp + c*akq
                for k in range(n):
                    apk, aqk = A[p][k], A[q][k]
                    A[p][k], A[q][k] = c*apk - s*aqk, s*apk + c*aqk
    return sorted(A[i][i] for i in range(n))

def _v377_curvn(gfun, x, deps):
    """For a diagonal metric diag(g_0, ..., g_n-1)(x) depending on the coordinates in deps: the Christoffel symbols Gamma^a_bc and the Riemann
    tensor R^a_bcd, from the metric's exact first and second derivatives (hyper-dual numbers)."""
    E = _V376HD; n = len(x)
    g = [v.a for v in gfun([E(xi) for xi in x])]
    dg = [[0.0]*n for _ in range(n)]; ddg = [[[0.0]*n for _ in range(n)] for _ in range(n)]
    for i in deps:
        for j in deps:
            v = gfun([E(xk, 1.0 if k == i else 0.0, 1.0 if k == j else 0.0) for k, xk in enumerate(x)])
            for a in range(n):
                dg[a][i] = v[a].b; ddg[a][i][j] = v[a].d
    dl = lambda i, j: 1.0 if i == j else 0.0
    def Gam(a, b, c):
        return (dl(a, c)*dg[a][b] + dl(a, b)*dg[a][c] - dl(b, c)*dg[b][a])/(2*g[a])
    def dGam(d, a, b, c):
        num = dl(a, c)*dg[a][b] + dl(a, b)*dg[a][c] - dl(b, c)*dg[b][a]
        dnum = dl(a, c)*ddg[a][d][b] + dl(a, b)*ddg[a][d][c] - dl(b, c)*ddg[b][d][a]
        return -dg[a][d]*num/(2*g[a]**2) + dnum/(2*g[a])
    G_ = [[[Gam(a, b, c) for c in range(n)] for b in range(n)] for a in range(n)]
    R = [[[[dGam(c, a, d, b) - dGam(d, a, c, b) + sum(G_[a][c][e]*G_[e][d][b] - G_[a][d][e]*G_[e][c][b] for e in range(n))
            for d in range(n)] for c in range(n)] for b in range(n)] for a in range(n)]
    return g, G_, R

