def _v378_hopf(z):
    """The Hopf map C^2 -> R^3, z -> z^dag sigma z, with |h(z)| = |z|^2; invariant under the Hopf circle z -> e^(i phi) z."""
    a, b = z
    return (2*(a.conjugate()*b).real, 2*(a.conjugate()*b).imag, abs(a)**2 - abs(b)**2)

def _v378_spinor(th, ph):
    """The section (cos(th/2), e^(i phi) sin(th/2)) of the Hopf bundle over the point (th, phi) of S^2."""
    return (complex(math.cos(th/2), 0), complex(math.cos(ph)*math.sin(th/2), math.sin(ph)*math.sin(th/2)))

def _v378_chern(N):
    """The first Chern number of the Hopf bundle by the lattice method (Fukui, Hatsugai and Suzuki, 2005): the sum of the plaquette phases
    arg(U1 U2 U3 U4) of the link variables U = <psi_i|psi_j> over an N x N grid of S^2, divided by 2 pi -- an integer for a fine enough grid.
    Each plaquette is taken theta before phi, the orientation (theta, phi) of XXVIII.12, whose c_1 for this section is 1.0000.  Returns the
    number and the largest plaquette phase."""
    th = [i*PI/N for i in range(N + 1)]; ph = [2*PI*j/N for j in range(N)]
    psi = [[_v378_spinor(th[i], ph[j]) for j in range(N)] for i in range(N + 1)]
    ip = lambda u, v: (u[0].conjugate()*v[0] + u[1].conjugate()*v[1])
    tot = 0.0; worst = 0.0
    for i in range(N):
        for j in range(N):
            j1 = (j + 1) % N
            pl = ip(psi[i][j], psi[i + 1][j])*ip(psi[i + 1][j], psi[i + 1][j1])*ip(psi[i + 1][j1], psi[i][j1])*ip(psi[i][j1], psi[i][j])
            a = math.atan2(pl.imag, pl.real); tot += a; worst = max(worst, abs(a))
    return tot/(2*PI), worst

def _v378_cap(N, i0):
    """The plaquette sum over the cap theta < theta_(i0) of the grid, in the orientation (theta, phi): the interior links cancel, and it is the
    argument of the links' product around the latitude theta_(i0), phi increasing, the Pancharatnam phase of XX.6."""
    th = [i*PI/N for i in range(N + 1)]; ph = [2*PI*j/N for j in range(N)]
    psi = [[_v378_spinor(th[i], ph[j]) for j in range(N)] for i in range(N + 1)]
    ip = lambda u, v: (u[0].conjugate()*v[0] + u[1].conjugate()*v[1])
    tot = 0.0
    for i in range(i0):
        for j in range(N):
            j1 = (j + 1) % N
            pl = ip(psi[i][j], psi[i + 1][j])*ip(psi[i + 1][j], psi[i + 1][j1])*ip(psi[i + 1][j1], psi[i][j1])*ip(psi[i][j1], psi[i][j])
            tot += math.atan2(pl.imag, pl.real)
    return tot, th[i0]

