def _v38_einst(cv):
    G = cv['G']; return [[cv['Ric'][a][b].val() - 0.5*G[a][b].val()*cv['R'].val() for b in range(4)] for a in range(4)]

def _v38_knt_report(G, f=None, X=None):
    """The KNT reconstruction from a metric's jets of order 4: K, its first derivatives, the residuals, the curl of K, the Einstein condition
    and, when the rescaling f is known, the errors against df and its Hessian."""
    kn = _v38_knt(G, first=True)
    K, dK = kn['K'], kn['dK']
    curl = max(abs(dK[e][b] - dK[b][e]) for e in range(4) for b in range(4))
    ein = max(abs(v) for row in _v38_einstein_cond(kn['cv'], K, dK) for v in row)
    out = {'K': K, 'dK': dK, 'res0': kn['res0'], 'res1': kn['res1'], 'scale': kn['scale'], 'cond': kn['cond'], 'curl': curl, 'ein': ein,
           'ric': _v38_maxabs(kn['cv']['Ric']), 'cv': kn['cv'], 'D': kn['D'], 'Cu': kn['Cu']}
    if f is not None:
        fj = f(X); out['eK'] = max(abs(K[a] - fj.d(a).val()) for a in range(4))
        out['edK'] = max(abs(dK[e][a] - fj.d(e).d(a).val()) for e in range(4) for a in range(4)); out['df'] = [fj.d(a).val() for a in range(4)]
    return out

def _v38_rep(G2, X2, x0, K, dK, c=0.0):
    """e^(-2 f_K) G with f_K = c + K.dx + dx.dK.dx/2, the conformal factor rebuilt to second order from the KNT vector: its curvature data."""
    S = G2[0][0].S
    ft = _v38_jsum(((X2[a] - x0[a])*K[a] for a in range(4)), S, S.N) + _v38_jsum(((X2[e] - x0[e])*(X2[a] - x0[a])*(0.5*dK[e][a])
                                                                                for e in range(4) for a in range(4)), S, S.N) + c
    return _v38_curv(_v38_scale(G2, ft*(-1.0)))

