def _v38_hopf(z):
    """h(z) = z^dag sigma z."""
    c = z[0].conjugate()*z[1]
    return [2*c.real, 2*c.imag, abs(z[0])**2 - abs(z[1])**2]

def _v38_solid(n1, n2, n3):
    """The signed solid angle of the geodesic triangle n1 n2 n3 on the unit sphere (Van Oosterom and Strackee)."""
    tri = (n1[0]*(n2[1]*n3[2] - n2[2]*n3[1]) - n1[1]*(n2[0]*n3[2] - n2[2]*n3[0]) + n1[2]*(n2[0]*n3[1] - n2[1]*n3[0]))
    dot = lambda a, b: sum(x*y for x, y in zip(a, b))
    return 2*math.atan2(tri, 1 + dot(n1, n2) + dot(n2, n3) + dot(n3, n1))

def _v38_spinor(n):
    """A unit spinor with Bloch vector n: (cos(th/2), e^(i ph) sin(th/2))."""
    th = math.acos(max(-1.0, min(1.0, n[2]))); ph = math.atan2(n[1], n[0])
    return [complex(math.cos(th/2)), cmath.exp(1j*ph)*math.sin(th/2)]

