def _v38_kron(*vs):
    out = [1.0 + 0j]
    for v in vs:
        out = [a*b for a in out for b in v]
    return out

def _v38_singlets(pairs):
    """The product of singlets on the given pairs of four qubits (a, b, c, d) = (0, 1, 2, 3), as a vector of C^16."""
    out = [0j]*16
    for bits in range(16):
        b = [(bits >> (3 - i)) & 1 for i in range(4)]
        amp = 1.0
        for (p, q) in pairs:
            if b[p] == b[q]: amp = 0.0; break
            amp *= (1 if b[p] == 0 else -1)/math.sqrt(2)
        out[bits] = complex(amp)
    return out

