    mu = [rng.uniform(0, 3) for _ in range(12)]
    Dr = unit_rows(rng, 12, 3)
    cls = [[0, 3, 6, 9], [1, 4, 7, 10], [2, 5, 8, 11]]; mcl = [0.4, 1.3, 2.2]
    muc = [0.0]*12
    for ci, labs in enumerate(cls):
        for k in labs: muc[k] = mcl[ci]
    base = []
    for labs in cls:
        v = [0j]*12
        for k in labs: v[k] = _v38_rc(rng)
        nv = math.sqrt(sum(abs(x)**2 for x in v)); base.append([x/nv for x in v])
    W = _v38_rUn(rng, 3)
    Dc = [[sum(W[F][i]*base[i][k] for i in range(3)) for k in range(12)] for F in range(3)]
    def probs(D, mus, L):
        out = []
        for F in range(3):
            row = []
            for Fp in range(3):
                amp = sum(D[Fp][k].conjugate()*cmath.exp(-1j*mus[k]*L)*D[F][k] for k in range(12)); row.append(abs(amp)**2)
