def _v381_gl2z(nmax=2):
    """The integer 2 x 2 matrices of determinant +-1 with entries from -nmax to nmax."""
    rg = range(-nmax, nmax + 1)
    return [((a, b), (c, d)) for a in rg for b in rg for c in rg for d in rg if abs(a*d - b*c) == 1]

