    tab = [(a, Q, Sf(1.0, a, Q)/(4*math.pi)) for a, Q in ((0.7, 0.0), (1.0, 0.0), (0.0, 1.0), (0.5, 0.5), (0.0, 0.7))]
    e_quad = e_next = 0.0
