    # (d) the lean of the Hopf circle toward the meridian
    def ric_yy_lean(Qe, Pm, r0, th0, psi, c1):
        Qm = math.sqrt(Qe*Qe + Pm*Pm); g, _ = _v39_kn4(S2, r0, th0, 1.0, 0.0, Qm)
        r = _V39Jet.var(S2, 0, r0); th = _V39Jet.var(S2, 1, th0); z = _v39_zero(S2, S2.N)
        A = [-1*Qe/r, z, z, -1*Pm*th.cos()]; c = c1*(r - r0) + 0.37
