    # (e) Entry 465's sliding leaf, and its flat limit
    def six(r0, th0, lapse2, f_, psi_, c_, at_, Pex=None):
        r = _V39Jet.var(S2, 0, r0); th = _V39Jet.var(S2, 1, th0); z = _v39_zero(S2, S2.N); one = _V39Jet.const(S2, 1.0)
        N2 = lapse2(r); f = f_(r); psi = psi_(r, N2); c = c_(r); at = at_(r, N2, c)
