        qq = qf(w); pp = pf(w); aa = af(w)
        rho2 = r*r + aa*aa - 2.0*aa*r*th.cos(); rho = rho2.sqrt(); c = qq/rho; Pm = pp/rho + lamq*qq*qq/rho2
        G = [[z for _ in range(6)] for _ in range(6)]
        G[0][1] = G[1][0] = 0.5*one; G[0][0] = Pm; G[2][2] = one; G[3][3] = r*r; G[4][4] = r*r*th.sin()*th.sin(); G[5][5] = one
