    # (h) the twisted pencil
    l = 1.7
    def mixed(eps, psi0, th0, chi0, pf, qf):
        psi = _V39Jet.var(S2, 0, psi0); th = _V39Jet.var(S2, 1, th0); chi = _V39Jet.var(S2, 2, chi0); z = _v39_zero(S2, S2.N); one = _V39Jet.const(S2, 1.0)
        s2 = chi.sin()*chi.sin(); sp2 = psi.sin()*psi.sin(); st2 = th.sin()*th.sin()
        a = [eps*pf(psi), z, z, eps*qf(psi)*st2]; w = a + [one]
        G = [[l*l*w[i]*w[j] for j in range(5)] for i in range(5)]
        G[0][0] = G[0][0] - one; G[1][1] = G[1][1] + l*l*s2; G[2][2] = G[2][2] + l*l*s2*sp2; G[3][3] = G[3][3] + l*l*s2*sp2*st2
        Ric = _v39_ricci(G, [1, 2, 4])[0]; av = [x.val() for x in a]
