    e_ct = max(max(abs(c[0] + 3*0.3/l), abs(c[1]), abs(c[2]), abs(c[3])) for c in cst_t)
    def simpson(f, a_, b_, n=2000):
        h = (b_ - a_)/n; return h/3*(f(a_) + f(b_) + sum((4 if k % 2 else 2)*f(a_ + k*h) for k in range(1, n)))
    I1 = simpson(math.sin, 0.0, math.pi); I3 = simpson(lambda x: math.sin(x)**3, 0.0, math.pi)
    cuts = [(cut, 2*simpson(lambda t: math.exp(t)/math.sin(math.exp(t)), math.log(cut), math.log(math.pi/2), 4000))
            for cut in (0.5, 0.1, 0.01, 0.001)]
