                Wm = _v39_cmm(_v39_cmm(F, Mx), _v39_dag(F)); total += 1
                i0, j0 = max(((i, j) for i in range(3) for j in range(3)), key=lambda ij: abs(Wm[ij[0]][ij[1]]))
                ph = abs(Wm[i0][j0])/Wm[i0][j0]; Wr = [[x*ph for x in row] for row in Wm]
