class _V39T3:
    """A truncated Taylor series f(t0 + t) = c0 + c1 t + c2 t^2 + c3 t^3 in one variable, exact to third order: the derivatives are c1, 2 c2, 6 c3."""
    def __init__(self, c): self.c = list(c) + [0.0]*(4 - len(c))
    @staticmethod
    def var(t0): return _V39T3([t0, 1.0])
    def _l(self, o): return o if isinstance(o, _V39T3) else _V39T3([o])
    def __add__(self, o): o = self._l(o); return _V39T3([a + b for a, b in zip(self.c, o.c)])
    __radd__ = __add__
    def __neg__(self): return _V39T3([-a for a in self.c])
    def __sub__(self, o): return self + (-self._l(o))
    def __rsub__(self, o): return self._l(o) - self
    def __mul__(self, o):
        o = self._l(o); return _V39T3([sum(self.c[i]*o.c[n - i] for i in range(n + 1)) for n in range(4)])
    __rmul__ = __mul__
    def __truediv__(self, o):
        o = self._l(o); q = [0.0]*4
        for n in range(4): q[n] = (self.c[n] - sum(q[i]*o.c[n - i] for i in range(n)))/o.c[0]
        return _V39T3(q)
    def __pow__(self, k):
        r = _V39T3([1.0])
        for _ in range(k): r = r*self
        return r
    def sc(self):
        d = _V39T3([0.0] + self.c[1:]); d2 = d*d; d3 = d2*d; s0, c0 = math.sin(self.c[0]), math.cos(self.c[0])
        cd = 1 - 0.5*d2; sd = d - d3*(1/6.0)
        return s0*cd + c0*sd, c0*cd - s0*sd

