    Ya = _v40_simpson(lambda t: 2/math.sqrt(lead*((e2 + (e3 - e2)*math.sin(t)**2) - e1)*(e4 - (e2 + (e3 - e2)*math.sin(t)**2))), 0, math.pi/2, 4000)
